const API_TOKEN = '1985d3b7ffcc266add8f005be68caf8ff8ec605f';
const BASE = 'https://api.pipedrive.com/v1';

const body = $input.first().json.body || $input.first().json;
const andConditions = body.andConditions || body.conditions || [];
const orConditions = body.orConditions || [];
const groupBy = body.groupBy || 'none';
const action = body.action || 'report';

if (action === 'metadata') {
    const [fieldsR, usersR, pipelinesR, stagesR] = await Promise.all([
      apiCall.call(this, 'GET', '/dealFields'),
      apiCall.call(this, 'GET', '/users'),
      apiCall.call(this, 'GET', '/pipelines'),
      apiCall.call(this, 'GET', '/stages')
    ]);
    let fields = (fieldsR.data||[]).map(f=>({field_id:f.id,key:f.key,name:f.name,type:f.field_type,options:f.options||[],filtering:f.filtering_allowed||false}));
    const extraFields = [
      {key:'owner_name',name:'Ім\'я власника',type:'auto'},
      {key:'person_name',name:'Ім\'я контакту',type:'auto'},
      {key:'org_name',name:'Назва організації',type:'auto'},
      {key:'cc_email',name:'Email угоди',type:'auto'},
      {key:'pipeline_id',name:'ID воронки',type:'auto'},
      {key:'formatted_value',name:'Форматована вартість',type:'auto'},
      {key:'formatted_weighted_value',name:'Форматована зважена вартість',type:'auto'},
      {key:'first_won_time',name:'Перший виграш',type:'auto'},
      {key:'rotten_time',name:'Час протухання',type:'auto'},
      {key:'owner_name',name:'Ім\'я власника',type:'auto'},
      {key:'files_count',name:'Кількість файлів',type:'auto'},
      {key:'notes_count',name:'Кількість нотаток',type:'auto'},
      {key:'followers_count',name:'Кількість підписників',type:'auto'},
      {key:'participants_count',name:'Кількість учасників',type:'auto'},
      {key:'products_count',name:'Кількість товарів',type:'auto'},
      {key:'active',name:'Активна',type:'auto'},
      {key:'deleted',name:'Видалена',type:'auto'},
      {key:'person_hidden',name:'Контакт прихований',type:'auto'},
      {key:'org_hidden',name:'Організація прихована',type:'auto'},
      {key:'next_activity_id',name:'ID наступного завдання',type:'auto'},
      {key:'next_activity_subject',name:'Тема наступного завдання',type:'auto'},
      {key:'next_activity_type',name:'Тип наступного завдання',type:'auto'},
      {key:'next_activity_duration',name:'Тривалість наступного завдання',type:'auto'},
      {key:'next_activity_note',name:'Нотатка наступного завдання',type:'auto'},
      {key:'next_activity_time',name:'Час наступного завдання',type:'auto'},
      {key:'last_activity_id',name:'ID останнього завдання',type:'auto'},
      {key:'local_won_date',name:'Локальна дата виграшу',type:'auto'},
      {key:'local_lost_date',name:'Локальна дата програшу',type:'auto'},
      {key:'local_close_date',name:'Локальна дата закриття',type:'auto'},
      {key:'stage_order_nr',name:'Порядок етапу',type:'auto'},
      {key:'source_lead_id',name:'ID джерела ліда',type:'auto'}
    ];
    const existingKeys = new Set(fields.map(f=>f.key));
    extraFields.forEach(f=>{if(!existingKeys.has(f.key)){fields.push({field_id:0,key:f.key,name:f.name,type:f.type,options:[],filtering:false});}});
    const users = (usersR.data||[]).map(u=>({id:u.id,name:u.name,active:u.active_flag}));
    const pipelines = (pipelinesR.data||[]).map(p=>({id:p.id,name:p.name}));
    const stagesObj = {};
    (stagesR.data||[]).forEach(s=>{if(!stagesObj[s.pipeline_id])stagesObj[s.pipeline_id]=[];stagesObj[s.pipeline_id].push({id:s.id,name:s.name});});
    return [{json:{fields,users,pipelines,stages:stagesObj}}];
  }

  if (!andConditions.length && !orConditions.length) return [{json:{error:'Додайте хоча б одну умову'}}];

async function apiCall(method, path, payload) {
  const opts = {method, url: BASE + path + (path.includes('?') ? '&' : '?') + 'api_token=' + API_TOKEN};
  if (payload) {opts.body = payload; opts.headers = {'Content-Type':'application/json'};}
  const r = await this.helpers.httpRequest(opts);
  return r;
}

let filterId = null;
try {
  // Create filter
  const filterPayload = {
    name: 'n8n_api_' + Date.now(),
    type: 'deals',
    conditions: {glue:'and', conditions:[{glue:'and', conditions: andConditions.map(c => ({object:'deal', field_id:c.field_id, operator:c.operator, value:c.value, extra_value:c.extra_value||null}))}, ...(orConditions.length ? [{glue:'or', conditions: orConditions.map(c => ({object:'deal', field_id:c.field_id, operator:c.operator, value:c.value, extra_value:c.extra_value||null}))}] : [])]}
  };
  const fRes = await apiCall.call(this, 'POST', '/filters', filterPayload);
  if (!fRes.success) return [{json:{error:'Filter error: ' + JSON.stringify(fRes)}}];
  filterId = fRes.data.id;

  // Count only?
  if (action === 'count') {
    const sRes = await apiCall.call(this, 'GET', '/deals/summary?filter_id=' + filterId);
    await apiCall.call(this, 'DELETE', '/filters/' + filterId);
    return [{json:{count: sRes.data.total_count, values: sRes.data.values_total}}];
  }

  // Fetch deals with pagination
  let allDeals = [], start = 0, hasMore = true, pages = 0;
  while (hasMore && pages < 20) {
    const dRes = await apiCall.call(this, 'GET', '/deals?filter_id=' + filterId + '&limit=500&start=' + start);
    if (dRes.data) allDeals = allDeals.concat(dRes.data);
    const p = dRes.additional_data && dRes.additional_data.pagination;
    hasMore = p && p.more_items_in_collection;
    if (hasMore) start = p.next_start;
    pages++;
  }

  // Delete filter
  await apiCall.call(this, 'DELETE', '/filters/' + filterId);
  filterId = null;

  // Process report - pass all fields as-is
  const rows = allDeals;

  const totals = {total:rows.length, won:0, lost:0, open:0, won_value:0, lost_value:0, open_value:0};
  rows.forEach(r => {
    if((r.status==='won')){totals.won++;totals.won_value+=r.value;}
    else if(r.status==='lost'){totals.lost++;totals.lost_value+=r.value;}
    else if(r.status==='open'){totals.open++;totals.open_value+=r.value;}
  });
  totals.conversion_rate = totals.total>0 ? Math.round(totals.won/totals.total*10000)/100 : 0;

  let groups = [];
  if (groupBy && groupBy !== 'none') {
    const gMap = {};
    rows.forEach(r => {
      const gk = groupBy==='owner' ? (typeof r.user_id==='object' ? r.user_id.name : r.user_id) : r.pipeline_id;
      if(!gMap[gk]) gMap[gk]={name:gk,total:0,won:0,lost:0,open:0,value:0};
      gMap[gk].total++; gMap[gk].value+=r.value;
      if((r.status==='won')) gMap[gk].won++;
      else if(r.status==='lost') gMap[gk].lost++;
      else gMap[gk].open++;
    });
    groups = Object.values(gMap).map(g => {g.conversion_rate=g.total>0?Math.round(g.won/g.total*10000)/100:0;return g;}).sort((a,b)=>b.total-a.total);
  }

  return [{json:{deals:rows, totals, groups, generated_at:new Date().toISOString()}}];
} catch(e) {
  if (filterId) try { await apiCall.call(this, 'DELETE', '/filters/' + filterId); } catch(e2) {}
  return [{json:{error: e.message || String(e)}}];
}
